mapper.update:
UPDATE pubcar_trip_mileage


        start_mileage = #{startMileage}


        ,end_mileage = #{endMileage}


        ,pass_mileage = #{passMileage}


        ,run_range = #{runRange}


        ,repair_fee = #{repairFee}


        ,oil_fee = #{oilFee}


        ,parking_fee = #{parkingFee}


        ,road_bridge_fee = #{roadBridgeFee}


WHERE community_id = #{communityId} AND trip_id = #{tripId} AND driver_id = #{driverId}

mapper.select:
SELECT ptm.end_mileage endMileage
FROM pubcar_trip_mileage ptm
LEFT JOIN pubcar_trip_car_num ptcn ON ptcn.trip_id = ptm.trip_id AND ptcn.driver_id = ptm.driver_id AND ptcn.status_cd = '0'
WHERE ptcn.car_id = #{carId} AND ptm.community_id = #{communityId}
ORDER BY ptm.create_time DESC
LIMIT 1;

SELECT COUNT(1) count
FROM pubcar_trip_mileage
WHERE status_cd = '0'
AND community_id = #{communityId}
AND trip_id = #{tripId}
AND driver_id = #{driverId}
AND (end_mileage IS NULL OR end_time IS NULL)

select b_id bId, mileage_id mileageId, start_mileage startMileage, end_mileage endMileage, pass_mileage passMileage,start_time startTime, end_time endTime,duration, car_condition carCondition,
       exception_desc exceptionDesc, car_condition_img carConditionImg, delay_time delayTime, delay_reason delayReason, trip_id tripId, driver_id driverId, operate, community_id communityId,
       run_range runRange, repair_fee repairFee, oil_fee oilFee, parking_fee parkingFee, road_bridge_fee roadBridgeFee
from business_pubcar_trip_mileage


        b_id= #{bId}


        and operate= #{operate}


        and community_id= #{communityId}

select m.mileage_id mileageId, m.start_mileage startMileage, m.end_mileage endMileage, m.start_time startTime, m.end_time endTime, m.trip_id tripId, m.driver_id driverId, m.community_id communityId,
       t.start_time applyStartTime, t.end_time applyEndTime, t.mileage applyMileage
from pubcar_trip_mileage m
left join pubcar_trip t on t.trip_id = m.trip_id
where m.status_cd= '0' and t.status_cd = '0'

    and m.trip_id= #{tripId}


    and m.driver_id= #{driverId}


    and m.community_id= #{communityId}

mapper.insert:
insert into pubcar_trip_mileage(mileage_id, start_mileage, start_time, car_condition, exception_desc, car_condition_img, trip_id, driver_id, b_id, status_cd, community_id)
select mileage_id, start_mileage, start_time, car_condition, exception_desc, car_condition_img, trip_id, driver_id, b_id, '0', community_id
from business_pubcar_trip_mileage


        b_id= #{bId}


        and operate= #{operate}

insert into pubcar_trip_mileage(`mileage_id`, `start_mileage`, `end_mileage`, `pass_mileage`, `start_time`, `end_time`, `duration`, `car_condition`, `run_range`, `repair_fee`, `oil_fee`, `parking_fee`, `road_bridge_fee`, `exception_desc`, `car_condition_img`, `delay_time`, `delay_reason`, `trip_id`, `driver_id`, `b_id`, `status_cd`, `community_id`)
select `mileage_id`, `start_mileage`, `end_mileage`, `pass_mileage`, `start_time`, `end_time`, `duration`, `car_condition`, `run_range`, `repair_fee`, `oil_fee`, `parking_fee`, `road_bridge_fee`, `exception_desc`, `car_condition_img`, `delay_time`, `delay_reason`, `trip_id`, `driver_id`, `b_id`, 0, `community_id`
from business_pubcar_trip_mileage


        b_id= #{bId}


        and operate= #{operate}

mapper.select:
select t.duration,t.mileage_id,t.mileage_id mileageId,t.create_time,t.create_time
createTime,t.start_mileage,t.start_mileage startMileage,t.trip_id,t.trip_id tripId,t.status_cd,t.status_cd
statusCd,t.end_mileage,t.end_mileage endMileage,t.b_id,t.b_id bId,t.community_id,t.community_id communityId
from pubcar_trip_mileage t


        t.duration= #{duration}


        and t.mileage_id= #{mileageId}


        and t.create_time= #{createTime}


        and t.start_mileage= #{startMileage}


        and t.trip_id= #{tripId}


        and t.status_cd= #{statusCd}


        and t.end_mileage= #{endMileage}


        and t.b_id= #{bId}


        and t.community_id= #{communityId}

    order by t.create_time desc

        limit #{page}, #{row}

