    t.status_cd = #{statusCd}

        ,t.b_id = #{newBId}


        , t.end_mileage= #{endMileage}


        , t.pass_mileage= #{passMileage}


        , t.end_time= #{endTime}


        , t.duration= #{duration}


        , t.delay_time= #{delayTime}


        , t.delay_reason= #{delayReason}


        , t.run_range= #{runRange}


        , t.repair_fee= #{repairFee}


        , t.oil_fee= #{oilFee}


        , t.parking_fee= #{parkingFee}


        , t.road_bridge_fee= #{roadBridgeFee}




        t.mileage_id= #{mileageId}


        and t.trip_id= #{tripId}


        and t.driver_id= #{driverId}


        and t.community_id= #{communityId}


        and t.b_id= #{bId}

